const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || item;
const suppliedSecret = headers['x-xvond-n8n-secret'] || headers['X-Xvond-N8N-Secret'];
const expectedSecret = $env.N8N_SHARED_SECRET;
const requestId = String(body.request_id || headers['x-xvond-request-id'] || '');
const action = String(body.action || '').trim();
const data = body.data && typeof body.data === 'object' ? body.data : {};

const fail = (error, code, extra = {}) => [{ json: { success: false, request_id: requestId, action, data: { code, ...extra }, error } }];

if (!expectedSecret || suppliedSecret !== expectedSecret) {
  return fail('Unauthorized workflow request', 'unauthorized');
}
if (!requestId || !body.company_id || !body.agent_id || !action) {
  return fail('Invalid workflow request contract', 'invalid_contract');
}

if (action === 'health_check') {
  return [{ json: { success: true, request_id: requestId, action, data: { status: 'ok', engine: 'workflow', company_id: body.company_id, agent_id: body.agent_id }, error: null } }];
}

const routes = {
  'booking.check_availability': { adapter: 'booking', mutates: false },
  'booking.execute': { adapter: 'booking', mutates: true },
  'booking.cancel': { adapter: 'booking', mutates: true },
  'send_email.execute': { adapter: 'email', mutates: true },
  'crm.upsert_contact': { adapter: 'crm', mutates: true },
  'crm.create_lead': { adapter: 'crm', mutates: true },
  'pos.create_order': { adapter: 'pos', mutates: true },
  'custom_api.execute': { adapter: 'custom_api', mutates: true },
  'notification.send': { adapter: 'notification', mutates: true }
};
let route = routes[action];
let actionKey = '';
let operation = '';
if (!route) {
  const match = action.match(/^([a-z0-9][a-z0-9_\-]{0,127})\.(check_availability|execute|cancel)$/i);
  if (!match) {
    return fail(`Unsupported workflow action: ${action}`, 'unsupported_action');
  }
  actionKey = match[1];
  operation = match[2];
  const configuredAction = data.action_config && typeof data.action_config === 'object' ? data.action_config : null;
  const declaredActionType = String(data.action_type || '').trim();
  const moduleName = String(configuredAction?.module || '').trim();
  const destination = configuredAction?.destination && typeof configuredAction.destination === 'object' ? configuredAction.destination : {};
  const destinationType = String(destination.type || '').trim();
  if (!configuredAction || !declaredActionType || declaredActionType !== actionKey || !moduleName) {
    return fail('Invalid generic business action contract', 'invalid_business_action', { action_key: actionKey || null });
  }
  route = {
    adapter: 'business',
    mutates: operation !== 'check_availability',
    action_key: actionKey,
    operation,
    module: moduleName,
    destination_type: destinationType || 'unconfigured'
  };
}

const idempotencyKey = String(data.idempotency_key || '');
if (route.mutates && !idempotencyKey) {
  return fail('Mutating workflow action requires idempotency_key', 'missing_idempotency_key', { adapter: route.adapter });
}

return fail(`Workflow adapter is not configured: ${route.adapter}`, 'provider_not_configured', { adapter: route.adapter, action_key: route.action_key || null, operation: route.operation || null, module: route.module || null, destination_type: route.destination_type || null, idempotency_key: idempotencyKey || null });
